    "unit_id": "BLLD_45-2019.D24.K1",
    "tieu_de_dieu": "Thử việc",
    "khoan_cha": "",
    "chu_don_vi": "Người sử dụng lao động và người lao động có thể thỏa thuận nội dung thử việc ghi trong hợp đồng lao động hoặc thỏa thuận về thử việc bằng việc giao kết hợp đồng thử việc."
   },
   "b": {
    "unit_id": "BLLD_45-2019.D34.K13",
    "tieu_de_dieu": "Các trường hợp chấm dứt hợp đồng lao động",
    "khoan_cha": "",
    "chu_don_vi": "Trường hợp thỏa thuận nội dung thử việc ghi trong hợp đồng lao động mà thử việc không đạt yêu cầu hoặc một bên hủy bỏ thỏa thuận thử việc."
   },
