   ]
  },
  {
   "cap_id": "P0081",
   "a": {
    "unit_id": "BLLD_45-2019.D25.K3",
    "tieu_de_dieu": "Thời gian thử việc",
    "khoan_cha": "Thời gian thử việc do hai bên thỏa thuận căn cứ vào tính chất và mức độ phức tạp của công việc nhưng chỉ được thử việc một lần đối với một công việc và bảo đảm điều kiện sau đây:",
    "chu_don_vi": "Không quá 30 ngày đối với công việc có chức danh nghề nghiệp cần trình độ chuyên môn, kỹ thuật trung cấp, công nhân kỹ thuật, nhân viên nghiệp vụ;"
   },
   "b": {
    "unit_id": "BLLD_45-2019.D48.K1",
    "tieu_de_dieu": "Trách nhiệm khi chấm dứt hợp đồng lao động",
    "khoan_cha": "",
    "chu_don_vi": "Trong thời hạn 14 ngày làm việc kể từ ngày chấm dứt hợp đồng lao động, hai bên có trách nhiệm thanh toán đầy đủ các khoản tiền có liên quan đến quyền lợi của mỗi bên, trừ trường hợp sau đây có thể kéo dài nhưng không được quá 30 ngày:",
    "cac_muc_con": [
     "Người sử dụng lao động không phải là cá nhân chấm dứt hoạt động;",
     "Người sử dụng lao động thay đổi cơ cấu, công nghệ hoặc vì lý do kinh tế;",
     "Chia, tách, hợp nhất, sáp nhập; bán, cho thuê, chuyển đổi loại hình doanh nghiệp; chuyển nhượng quyền sở hữu, quyền sử dụng tài sản của doanh nghiệp, hợp tác xã;",
     "Do thiên tai, hỏa hoạn, địch họa hoặc dịch bệnh nguy hiểm."
    ]
   },
   "vi_tu_chung": [
    "exceed_30_days"
   ]
  },
  {
   "cap_id": "P0082",
   "a": {
    "unit_id": "BLLD_45-2019.D27.K1",
    "tieu_de_dieu": "Kết thúc thời gian thử việc",
    "khoan_cha": "",
    "chu_don_vi": "Khi kết thúc thời gian thử việc, người sử dụng lao động phải thông báo kết quả thử việc cho người lao động.\nTrường hợp thử việc đạt yêu cầu thì người sử dụng lao động tiếp tục thực hiện hợp đồng lao động đã giao kết đối với trường hợp thỏa thuận thử việc trong hợp đồng lao động hoặc phải giao kết hợp đồng lao động đối với trường hợp giao kết hợp đồng thử việc.\nTrường hợp thử việc không đạt yêu cầu thì chấm dứt hợp đồng lao động đã giao kết hoặc hợp đồng thử việc."
   },
   "b": {
    "unit_id": "BLLD_45-2019.D32.K2",
    "tieu_de_dieu": "Làm việc không trọn thời gian",
    "khoan_cha": "",
    "chu_don_vi": "Người lao động thỏa thuận với người sử dụng lao động làm việc không trọn thời gian khi giao kết hợp đồng lao động."
   },
   "vi_tu_chung": [
